"""Print the human turns and the assistant's visible text from a transcript.

Usage: python3 -I extract.py <transcript.jsonl> [--assistant]
"""
import json
import sys

path = sys.argv[1]
show_assistant = "--assistant" in sys.argv

with open(path, encoding="utf-8") as f:
    for n, line in enumerate(f, 1):
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            continue
        kind = rec.get("type")
        msg = rec.get("message") or {}
        content = msg.get("content")
        if kind == "user":
            if isinstance(content, str):
                texts = [content]
            elif isinstance(content, list):
                texts = [c.get("text", "") for c in content
                         if isinstance(c, dict) and c.get("type") == "text"]
            else:
                texts = []
            for t in texts:
                if t.strip():
                    print(f"\n===== [{n}] USER =====\n{t}")
        elif kind == "assistant" and show_assistant:
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get("type") == "text" and c.get("text", "").strip():
                        print(f"\n----- [{n}] ASSISTANT -----\n{c['text']}")

