// Render a Mermaid file the way github.com does, as of 2026-10-23:
// Mermaid 12.2.0, GitHub's initialize() settings, and GitHub's DOMPurify
// allowlist applied to the SVG. Writes a PNG per theme and prints the
// diagram's natural size, which GitHub scales down to fit the page width.
//
// Usage: node render.cjs <input.mmd> <output-prefix> [--width=880] [--themes=light,dark]

const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");

const globalRoot = execSync("npm root -g").toString().trim();
const { chromium } = require(path.join(globalRoot, "playwright"));

const RENDER_DIR = path.join(__dirname, "..", "render", "node_modules");
const MERMAID_JS = path.join(RENDER_DIR, "mermaid", "dist", "mermaid.min.js");
const PURIFY_JS = path.join(RENDER_DIR, "dompurify", "dist", "purify.js");

// Copied from GitHub's viewscreen bundle (mermaidMarkdown-5b99bd9a2037271fa4cf.js).
const GITHUB_ALLOWED_TAGS = ["svg","a","altglyph","altglyphdef","altglyphitem","animatecolor","animatemotion","animatetransform","circle","clippath","defs","desc","ellipse","filter","font","g","glyph","glyphref","hkern","image","line","lineargradient","marker","mask","metadata","mpath","path","pattern","polygon","polyline","radialgradient","rect","stop","style","switch","symbol","text","textpath","title","tref","tspan","view","vkern","feBlend","feColorMatrix","feComponentTransfer","feComposite","feConvolveMatrix","feDiffuseLighting","feDisplacementMap","feDistantLight","feDropShadow","feFlood","feFuncA","feFuncB","feFuncG","feFuncR","feGaussianBlur","feImage","feMerge","feMergeNode","feMorphology","feOffset","fePointLight","feSpecularLighting","feSpotLight","feTile","feTurbulence","b","blockquote","br","dd","div","dl","dt","em","foreignObject","h1","h2","h3","h4","h5","h6","h7","h8","hr","i","li","ul","ol","p","pre","span","strike","strong","table","tbody","td","tfoot","th","thead","tr"];

const args = process.argv.slice(2);
const input = args[0];
const prefix = args[1];
const opt = (name, dflt) => {
  const a = args.find((x) => x.startsWith(`--${name}=`));
  return a ? a.split("=")[1] : dflt;
};
const width = Number(opt("width", "880"));
const themes = opt("themes", "light,dark").split(",");

(async () => {
  const text = fs.readFileSync(input, "utf8");
  const browser = await chromium.launch();
  for (const theme of themes) {
    const page = await browser.newPage({ deviceScaleFactor: 2, viewport: { width: width + 40, height: 1000 } });
    const bg = theme === "dark" ? "#0d1117" : "#ffffff";
    await page.setContent(`<!doctype html><html><head><meta charset="utf-8"></head>
      <body style="margin:0;padding:20px;background:${bg}">
      <div id="mermaid-view-template"></div>
      <div id="out" style="width:${width}px"></div></body></html>`);
    await page.addScriptTag({ path: MERMAID_JS });
    await page.addScriptTag({ path: PURIFY_JS });
    const result = await page.evaluate(async ({ text, theme, allowed }) => {
      const warnings = [];
      const origWarn = console.warn;
      console.warn = (...a) => { warnings.push(a.join(" ")); origWarn(...a); };
      mermaid.initialize({
        startOnLoad: false,
        secure: ["secure", "securityLevel", "startOnLoad", "maxTextSize"],
        securityLevel: "antiscript",
        flowchart: { diagramPadding: 48 },
        gantt: { useWidth: 1200 },
        pie: { useWidth: 1200 },
        sequence: { diagramMarginY: 40 },
        theme: theme === "dark" ? "dark" : "default",
        logLevel: 2,
      });
      let svg;
      try {
        ({ svg } = await mermaid.render("diagram", text, document.getElementById("mermaid-view-template")));
      } catch (e) {
        return { error: String(e && e.message ? e.message : e) };
      }
      const before = (svg.match(/<[a-zA-Z][\w:-]*/g) || []).map((t) => t.slice(1).toLowerCase());
      const frag = DOMPurify.sanitize(svg, {
        RETURN_DOM_FRAGMENT: true,
        HTML_INTEGRATION_POINTS: { foreignobject: true },
        ALLOWED_TAGS: allowed,
        ADD_ATTR: ["transform-origin", "dominant-baseline"],
      });
      const allowedLower = new Set(allowed.map((t) => t.toLowerCase()));
      const stripped = [...new Set(before.filter((t) => !allowedLower.has(t)))];
      const el = frag.querySelector("svg");
      const vb = (el.getAttribute("viewBox") || "").split(" ");
      if (!el.hasAttribute("height")) el.setAttribute("height", vb[3]);
      el.setAttribute("preserveAspectRatio", "xMinYMin");
      const div = document.createElement("div");
      div.classList.add("mermaid");
      div.appendChild(frag);
      document.getElementById("out").replaceChildren(div);
      return { viewBox: vb.map(Number), stripped, warnings };
    }, { text, theme, allowed: GITHUB_ALLOWED_TAGS });
    if (result.error) {
      console.error(`[${theme}] RENDER ERROR: ${result.error}`);
      process.exitCode = 1;
      await page.close();
      continue;
    }
    const [, , w, h] = result.viewBox;
    const scale = Math.min(1, width / w);
    const out = `${prefix}-${theme}.png`;
    await page.locator("#out").screenshot({ path: out });
    console.log(`[${theme}] ${out}: natural ${Math.round(w)}x${Math.round(h)}px, shown at ${Math.round(scale * 100)}% in a ${width}px column`);
    if (result.stripped.length) console.log(`[${theme}] tags GitHub would strip: ${result.stripped.join(", ")}`);
    if (result.warnings.length) console.log(`[${theme}] warnings: ${result.warnings.slice(0, 5).join(" | ")}`);
    await page.close();
  }
  await browser.close();
})();

